    /* =====================================================================
       RAQAMLI / DINAMIK MATNLAR (lug'atga sig'maydiganlar)
       ===================================================================== */
    var MONTHS_UZ = ['yanvar', 'fevral', 'mart', 'aprel', 'may', 'iyun', 'iyul', 'avgust', 'sentabr', 'oktabr', 'noyabr', 'dekabr'];
    var MONTHS_I18N = {
        ru: ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'],
        en: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
    };
    function durText(h, m) {
        var u = locale === 'ko' ? ['시간', '분'] : locale === 'ru' ? [' ч', ' мин'] : [' h', ' min'];
        var parts = [];
        if (h) parts.push(h + u[0]);
        if (m || !h) parts.push((m || 0) + u[1]);
        return parts.join(' ');
    }
    function parseDur(s) {
        var a = s.match(/(\d+) soat/), b = s.match(/(\d+) daqiqa/);
        return durText(a ? parseInt(a[1], 10) : 0, b ? parseInt(b[1], 10) : 0);
    }
    function translateDynamic(s) {
        var L = locale, m, i;
        if (L !== 'ru' && L !== 'en' && L !== 'ko') return null;
        var DUR = '(\\d+ soat(?: \\d+ daqiqa)?|\\d+ daqiqa)';
        var HM = '(\\d{2}:\\d{2})';
        function pick(ru, en, ko) { return L === 'ru' ? ru : L === 'en' ? en : ko; }

        /* "5 soniya", "6 soat 30 daqiqa" */
        if ((m = s.match(/^(\d+) soniya$/))) return pick(m[1] + ' сек.', m[1] + ' sec', m[1] + '초');
        if ((m = s.match(new RegExp('^' + DUR + '$')))) return parseDur(m[1]);

        /* Sana: "1-oktabr" (dmy), "Oktabr 1" (mdy) */
        if ((m = s.match(/^(\d{1,2})-([a-z]+)$/)) && (i = MONTHS_UZ.indexOf(m[2])) > -1) {
            return L === 'ko' ? (i + 1) + '월 ' + m[1] + '일' : m[1] + ' ' + MONTHS_I18N[L][i];
        }
        if ((m = s.match(/^([A-Z][a-z]+) (\d{1,2})$/)) && (i = MONTHS_UZ.indexOf(m[1].toLowerCase())) > -1) {
            return L === 'ko' ? (i + 1) + '월 ' + m[2] + '일' : L === 'ru' ? m[2] + ' ' + MONTHS_I18N.ru[i] : MONTHS_I18N.en[i] + ' ' + m[2];
        }

        /* Dam olish vaqti holat matnlari */
        if ((m = s.match(new RegExp('^Tinch soat boshlanishiga ' + DUR + ' qoldi \\(' + HM + '\\)\\.$')))) {
            return pick('До начала тихих часов осталось ' + parseDur(m[1]) + ' (' + m[2] + ').',
                        'Quiet hours start in ' + parseDur(m[1]) + ' (' + m[2] + ').',
                        '방해 금지 시간까지 ' + parseDur(m[1]) + ' 남았습니다 (' + m[2] + ').');
        }
        if ((m = s.match(new RegExp('^Yozishmalar ' + DUR + 'dan keyin, soat ' + HM + ' da ochiladi\\.$')))) {
            return pick('Переписка откроется через ' + parseDur(m[1]) + ', в ' + m[2] + '.',
                        'Messaging opens in ' + parseDur(m[1]) + ', at ' + m[2] + '.',
                        parseDur(m[1]) + ' 후 ' + m[2] + '에 메시지가 다시 열립니다.');
        }
        if ((m = s.match(new RegExp('^Tungi oraliq: ' + HM + ' dan ertasi kuni ' + HM + ' gacha yozishmalar ochiq\\.$')))) {
            return pick('Ночной интервал: переписка открыта с ' + m[1] + ' до ' + m[2] + ' следующего дня.',
                        'Overnight range: messaging is open from ' + m[1] + ' until ' + m[2] + ' the next day.',
                        '야간 설정: ' + m[1] + '부터 다음 날 ' + m[2] + '까지 메시지가 열려 있습니다.');
        }
        if ((m = s.match(new RegExp("^Yozishmalar " + HM + " dan " + HM + " gacha ochiq, undan tashqarida eslatma ko'rsatiladi\\.$")))) {
            return pick('Переписка открыта с ' + m[1] + ' до ' + m[2] + ', вне этого времени показывается напоминание.',
                        'Messaging is open from ' + m[1] + ' to ' + m[2] + '; outside this range a reminder is shown.',
                        m[1] + '부터 ' + m[2] + '까지 메시지가 열려 있으며, 그 외 시간에는 안내가 표시됩니다.');
        }

        /* Xotira: "3 / 5 yoqilgan" va "Rasmlar — Wi-Fi" */
        if ((m = s.match(/^(\d+) \/ (\d+) yoqilgan$/))) {
            return pick('включено ' + m[1] + ' из ' + m[2], m[1] + ' of ' + m[2] + ' on', m[2] + '개 중 ' + m[1] + '개 켜짐');
        }
        if ((m = s.match(/^(.+) — (Wi-Fi|mobil internet)$/))) {
            var label = currentMap()[m[1]] || m[1];
            var net = m[2] === 'Wi-Fi' ? 'Wi-Fi' : pick('мобильный интернет', 'mobile data', '모바일 데이터');
            return label + ' — ' + net;
        }

        /* Fayl / server xatolari */
        if ((m = s.match(/^Fayl juda katta \((.+)\)\. Maksimal hajm: (\d+) MB\.$/))) {
            return pick('Файл слишком большой (' + m[1] + '). Максимальный размер: ' + m[2] + ' МБ.',
                        'File is too large (' + m[1] + '). Maximum size: ' + m[2] + ' MB.',
                        '파일이 너무 큽니다 (' + m[1] + '). 최대 크기: ' + m[2] + 'MB.');
        }
        if ((m = s.match(/^Xatolik \((\d+)\)\.$/))) return pick('Ошибка (' + m[1] + ').', 'Error (' + m[1] + ').', '오류 (' + m[1] + ').');
        if ((m = s.match(/^Fayl topilmadi yoki ochilmadi: (.+)$/))) {
            return pick('Файл не найден или не открывается: ' + m[1], "File not found or couldn't be opened: " + m[1], '파일을 찾을 수 없거나 열 수 없습니다: ' + m[1]);
        }
        if ((m = s.match(/^Fayl topilmadi: (.+)$/))) {
            return pick('Файл не найден: ' + m[1], 'File not found: ' + m[1], '파일을 찾을 수 없습니다: ' + m[1]);
        }

        /* "Joy · hozir faol", "Windows · Brauzer" — bo'laklab tarjima */
        if (s.indexOf(' · ') > -1) {
            var changed = false;
            var out = s.split(' · ').map(function (p) {
                var t = currentMap()[p] || translateDynamic(p);
                if (t) changed = true;
                return t || p;
            });
            if (changed) return out.join(' · ');
        }
        return null;
    }

    /* V3 tarjimalarni mavjud settings lug'atiga qo'shish */
    ['ru', 'en', 'ko'].forEach(function (L) {
        settingsDictionaries[L] = Object.assign(settingsDictionaries[L] || {}, settingsV3[L]);
    });

    var nodeSources = new WeakMap();
    var nodeLast = new WeakMap();
